scenes.css:
.vw{position:absolute;left:96px;right:150px;top:490px}
.vg{display:grid;grid-template-columns:repeat(6,1fr);gap:18px;width:834px}
.sv{height:96px;border-radius:16px;background:#fff;border:3px solid var(--blue);position:relative}
.sv i{position:absolute;left:18px;right:18px;height:8px;border-radius:4px;background:var(--blue);opacity:.35}
.sv i:nth-child(1){top:26px}.sv i:nth-child(2){top:48px}.sv b{position:absolute;right:14px;bottom:14px;width:16px;height:16px;border-radius:50%;background:var(--blue)}
.sv.off{border-color:#C9D2E0;background:#EEF1F6}.sv.off i{background:#C9D2E0}.sv.off b{background:#D33}
.sv .x{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:72px;font-weight:900;color:#D33;opacity:0}
.vt{margin-top:30px;font-size:52px;font-weight:700;color:var(--ink);opacity:0}
.vt b{color:var(--blue);font-weight:900}.vt b.o{color:#EA6A12}
#vt1{margin-top:36px}
.vn{margin-top:22px;font-size:30px;color:var(--sub)}

scenes.js:
const g=document.getElementById('vg');const S=[];const OFF=[1,3,4,8,10,13,15,16];for(let i=0;i<18;i++){const d=document.createElement('div');d.className='sv';d.innerHTML='<i></i><i></i><b></b><span class="x">×</span>';g.appendChild(d);S.push(d);}
const ez=x=>x<=0?0:x>=1?1:1-Math.pow(1-x,3);const t1=document.getElementById('vt1'),t2=document.getElementById('vt2');
__tick.push(t=>{S.forEach((d,i)=>{const k=OFF.indexOf(i);const on=k>=0&&t>0.6+k*0.12;d.classList.toggle('off',on);d.querySelector('.x').style.opacity=on?ez((t-0.6-k*0.12)/0.2).toFixed(3):0;
const b2=(__B[1]||2.2);if(k<0){const h=ez((t-b2)/0.5);d.style.background='rgba(234,106,18,'+(0.22*h).toFixed(3)+')';d.style.borderColor=h>0.5?'#EA6A12':'';}});
const a=ez((t-0.5)/0.35);t1.style.opacity=a.toFixed(3);const c=ez((t-(__B[1]||2.2))/0.35);t2.style.opacity=c.toFixed(3);t2.style.transform='translateY('+(20*(1-c)).toFixed(1)+'px)';});
